import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"Day 18: Demystifying Device Trees (DTS, DTB, DTC)","description":"","frontmatter":{},"headers":[],"relativePath":"day18-device-trees-dts-dtb-dtc.md","filePath":"day18-device-trees-dts-dtb-dtc.md"}'),o={name:"day18-device-trees-dts-dtb-dtc.md"};function n(d,e,r,l,h,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="day-18-demystifying-device-trees-dts-dtb-dtc" tabindex="-1">Day 18: Demystifying Device Trees (DTS, DTB, DTC) <a class="header-anchor" href="#day-18-demystifying-device-trees-dts-dtb-dtc" aria-label="Permalink to &quot;Day 18: Demystifying Device Trees (DTS, DTB, DTC)&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Explain the historical problem Device Trees solve in the ARM ecosystem</li><li>Read and interpret the syntax of a Device Tree Source (<code>.dts</code>) file</li><li>Manually compile a <code>.dts</code> into a binary blob (<code>.dtb</code>) using the Device Tree Compiler (<code>dtc</code>)</li><li>Understand how the bootloader passes the DTB to the Linux kernel</li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day17-busybox-deep-dive.html">Day 17: BusyBox Deep Dive</a></li></ul></div><hr><h2 id="_1-the-hardware-discovery-problem" tabindex="-1">1. The Hardware Discovery Problem <a class="header-anchor" href="#_1-the-hardware-discovery-problem" aria-label="Permalink to &quot;1. The Hardware Discovery Problem&quot;">​</a></h2><p>If you install Linux on an Intel or AMD desktop PC (x86 architecture), the kernel doesn&#39;t need to be told where the USB ports, PCIe slots, or RAM modules are physically wired on the motherboard. It asks the <strong>BIOS/UEFI</strong> and the <strong>ACPI</strong> tables. The hardware is self-discoverable.</p><p><strong>Embedded ARM processors (SoCs) do not have a BIOS or ACPI.</strong></p><p>Historically, before 2011, Linux kernel developers had to write thousands of lines of hardcoded C structs for <em>every single ARM board ever manufactured</em>. If you designed a new BeagleBone clone with the LED wired to a different pin, you had to recompile the entire Linux kernel. Linus Torvalds famously got so frustrated with this mess that he mandated a change.</p><p>The solution adopted was the <strong>Device Tree</strong>.</p><hr><h2 id="_2-what-is-a-device-tree" tabindex="-1">2. What is a Device Tree? <a class="header-anchor" href="#_2-what-is-a-device-tree" aria-label="Permalink to &quot;2. What is a Device Tree?&quot;">​</a></h2><p>A Device Tree is a strict data structure that describes the physical hardware layout of a board to the operating system.</p><p>Instead of hardcoding hardware addresses into the Linux kernel C code, the kernel is compiled completely ignorant of the board it will run on. During boot, the bootloader (like U-Boot) hands the kernel a <strong>binary file</strong> (the Device Tree) that says: <em>&quot;You have 512MB of RAM at address 0x80000000, a UART serial port at 0x44E09000, and an LED wired to GPIO pin 5.&quot;</em></p><p>This allows the exact same Linux Kernel binary (<code>zImage</code>) to boot on hundreds of completely different ARM boards.</p><hr><h2 id="_3-the-3-d-s-dts-dtc-and-dtb" tabindex="-1">3. The 3 D&#39;s: DTS, DTC, and DTB <a class="header-anchor" href="#_3-the-3-d-s-dts-dtc-and-dtb" aria-label="Permalink to &quot;3. The 3 D&#39;s: DTS, DTC, and DTB&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Acronym</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><strong>DTS</strong></td><td>Device Tree Source</td><td>Human-readable text files containing the hardware description. Similar syntax to JSON or C structs.</td></tr><tr><td><strong>DTC</strong></td><td>Device Tree Compiler</td><td>A command-line tool that parses <code>.dts</code> text files and compiles them into binary format.</td></tr><tr><td><strong>DTB</strong></td><td>Device Tree Blob</td><td>The compiled binary output of the DTC. This is the actual file loaded into RAM by the bootloader and read by the Kernel.</td></tr></tbody></table><hr><h2 id="_4-reading-a-device-tree-source-dts" tabindex="-1">4. Reading a Device Tree Source (<code>.dts</code>) <a class="header-anchor" href="#_4-reading-a-device-tree-source-dts" aria-label="Permalink to &quot;4. Reading a Device Tree Source (\`.dts\`)&quot;">​</a></h2><p>A <code>.dts</code> file is organized as a tree of <strong>nodes</strong> and <strong>properties</strong>. Here is a highly simplified example of a UART serial port node:</p><div class="language-dts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/dts-v1/;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/ {</span></span>
<span class="line"><span>    model = &quot;TI AM335x BeagleBone Black&quot;;</span></span>
<span class="line"><span>    compatible = &quot;ti,am335x-bone-black&quot;, &quot;ti,am335x-bone&quot;, &quot;ti,am33xx&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    cpus {</span></span>
<span class="line"><span>        cpu@0 {</span></span>
<span class="line"><span>            compatible = &quot;arm,cortex-a8&quot;;</span></span>
<span class="line"><span>        };</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    uart0: serial@44e09000 {</span></span>
<span class="line"><span>        compatible = &quot;ti,am3352-uart&quot;, &quot;ti,omap3-uart&quot;;</span></span>
<span class="line"><span>        reg = &lt;0x44e09000 0x2000&gt;;</span></span>
<span class="line"><span>        interrupts = &lt;72&gt;;</span></span>
<span class="line"><span>        status = &quot;okay&quot;;</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>};</span></span></code></pre></div><h3 id="key-concepts-in-the-syntax" tabindex="-1">Key Concepts in the Syntax <a class="header-anchor" href="#key-concepts-in-the-syntax" aria-label="Permalink to &quot;Key Concepts in the Syntax&quot;">​</a></h3><ol><li><strong>Nodes (<code>serial@44e09000</code>)</strong>: Represent physical devices. The text before the <code>@</code> is the generic name. The text after is the base memory address of the hardware register.</li><li><strong>Labels (<code>uart0:</code>)</strong>: A variable name you can use to reference this node elsewhere in the file.</li><li><strong><code>compatible</code></strong>: The most important property! This tells the Linux kernel exactly which C driver file to load for this piece of hardware.</li><li><strong><code>reg</code></strong>: The physical memory address and length (<code>0x2000</code> bytes) assigned to this hardware block.</li><li><strong><code>status</code></strong>: Can be <code>&quot;okay&quot;</code> (enabled) or <code>&quot;disabled&quot;</code>. SoCs have hundreds of peripherals; most are disabled by default to save power unless a board actually wires them up.</li></ol><hr><h2 id="_5-compiling-with-dtc" tabindex="-1">5. Compiling with <code>dtc</code> <a class="header-anchor" href="#_5-compiling-with-dtc" aria-label="Permalink to &quot;5. Compiling with \`dtc\`&quot;">​</a></h2><p>In Yocto, BitBake compiles the device trees automatically during the <code>do_compile</code> phase of the <code>linux-yocto</code> (kernel) recipe. However, as an embedded engineer, you will frequently compile them manually while prototyping hardware.</p><h3 id="installing-dtc-on-your-host" tabindex="-1">Installing DTC on your host <a class="header-anchor" href="#installing-dtc-on-your-host" aria-label="Permalink to &quot;Installing DTC on your host&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device-tree-compiler</span></span></code></pre></div><h3 id="compiling-dts-dtb" tabindex="-1">Compiling (DTS -&gt; DTB) <a class="header-anchor" href="#compiling-dts-dtb" aria-label="Permalink to &quot;Compiling (DTS -&gt; DTB)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dtc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dtb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> am335x-boneblack.dtb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> am335x-boneblack.dts</span></span></code></pre></div><h3 id="decompiling-dtb-dts" tabindex="-1">Decompiling (DTB -&gt; DTS) <a class="header-anchor" href="#decompiling-dtb-dts" aria-label="Permalink to &quot;Decompiling (DTB -&gt; DTS)&quot;">​</a></h3><p>If you are handed a <code>.dtb</code> blob without the source code, you can reverse-engineer it!</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dtc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dtb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> decompiled.dts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unknown-board.dtb</span></span></code></pre></div><hr><h2 id="_6-how-the-bootloader-uses-the-dtb" tabindex="-1">6. How the Bootloader uses the DTB <a class="header-anchor" href="#_6-how-the-bootloader-uses-the-dtb" aria-label="Permalink to &quot;6. How the Bootloader uses the DTB&quot;">​</a></h2><p>Let&#39;s revisit the BeagleBone boot sequence from Day 3.</p><p>When U-Boot takes control of the system, it reads the SD card and loads <strong>two</strong> files into RAM:</p><ol><li><code>zImage</code> (The Linux Kernel) loaded at address <code>0x82000000</code></li><li><code>am335x-boneblack.dtb</code> (The Device Tree Blob) loaded at address <code>0x88000000</code></li></ol><p>U-Boot then issues the command to start the kernel, passing the address of the DTB as an argument:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># U-Boot prompt command: bootz &lt;kernel_addr&gt; - &lt;dtb_addr&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">U-Boot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bootz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x82000000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x88000000</span></span></code></pre></div><p>The kernel wakes up, looks at <code>0x88000000</code>, parses the hardware map, and begins loading the appropriate <code>compatible</code> drivers.</p><hr><h2 id="_7-hands-on-lab-exercises" tabindex="-1">7. Hands-On Lab Exercises <a class="header-anchor" href="#_7-hands-on-lab-exercises" aria-label="Permalink to &quot;7. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 18.1: Locate the Compiled DTB</p><ol><li>Navigate to your Yocto deploy directory for the BeagleBone build from Day 3 or 4: <code>build/tmp/deploy/images/beaglebone/</code></li><li>Run <code>ls *.dtb</code>. You will see <code>am335x-boneblack.dtb</code>. This is the exact blob WIC copies into the FAT32 boot partition of your SD card image.</li></ol></div><div class="tip custom-block"><p class="custom-block-title">LAB 18.2: Reverse Compile the Blobs</p><ol><li>Ensure the <code>dtc</code> tool is installed on your Ubuntu host (<code>sudo apt install device-tree-compiler</code>).</li><li>Run <code>dtc -I dtb -O dts -o my_dts_file.dts am335x-boneblack.dtb</code></li><li>Open <code>my_dts_file.dts</code> in VS Code or <code>nano</code>.</li><li>Search (CTRL+F) for <code>leds</code>. Look at how the GPIO pins are mapped to the physical blue LEDs on the BeagleBone!</li></ol></div><hr><h2 id="_8-further-reading" tabindex="-1">8. Further Reading <a class="header-anchor" href="#_8-further-reading" aria-label="Permalink to &quot;8. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Device Tree Usage Guide (eLinux)</td><td><a href="https://elinux.org/Device_Tree_Usage" target="_blank" rel="noreferrer">elinux.org/Device_Tree_Usage</a></td></tr><tr><td>Linux Kernel DT Bindings</td><td><a href="https://www.kernel.org/doc/Documentation/devicetree/bindings/" target="_blank" rel="noreferrer">kernel.org/doc/Documentation/devicetree/bindings/</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day17-busybox-deep-dive">← Day 17: BusyBox Deep Dive</a><a href="/day19-kernel-configuration-menuconfig">Day 19: Kernel Configuration →</a></div>`,50)])])}const u=a(o,[["render",n]]);export{b as __pageData,u as default};
